statements:
create table if not exists public.vertice_data_connections(
 id uuid primary key default gen_random_uuid(),
 institution_id uuid not null references public.vertice_institutions(id) on delete cascade,
 tipo text not null check (tipo in ('api','sql','agente','onedrive')),
 fornecedor text not null check (char_length(fornecedor) between 2 and 60),
 rotulo text not null check (char_length(rotulo) between 2 and 80),
 config jsonb not null default '{}'::jsonb,
 vault_secret_id uuid,
 escopo text not null default 'agregado' check (escopo in ('agregado','nominal')),
 status text not null default 'pendente' check (status in ('pendente','ativa','erro','pausada')),
 aceite_operador_em timestamptz not null,
 aceite_por uuid not null,
 ultimo_teste_em timestamptz,
 ultimo_sync_em timestamptz,
 ultimo_erro text,
 created_by uuid not null,
 created_at timestamptz not null default now(),
 updated_at timestamptz not null default now()
);
create index if not exists vertice_data_connections_inst on public.vertice_data_connections(institution_id);
create table if not exists public.vertice_data_connection_runs(
 id bigint generated always as identity primary key,
 connection_id uuid not null references public.vertice_data_connections(id) on delete cascade,
 institution_id uuid not null,
 acao text not null check (acao in ('criar','testar','sincronizar','pausar','retomar','revogar')),
 status text not null check (status in ('ok','erro')),
 detalhe text,
 acionado_por uuid,
 created_at timestamptz not null default now()
);
create index if not exists vertice_data_connection_runs_conn on public.vertice_data_connection_runs(connection_id, created_at desc);
alter table public.vertice_data_connections enable row level security;
alter table public.vertice_data_connection_runs enable row level security;

create or replace function public.vertice_connection_authorize(p_institution uuid)
returns boolean language sql stable set search_path to '' as $$
 select coalesce(auth.uid() is not null and auth.jwt()->>'aal'='aal2'
   and vertice_private.has_role(p_institution,array['gestor']),false);
$$;

revoke all on public.vertice_data_connections from anon, authenticated;
revoke all on public.vertice_data_connection_runs from anon, authenticated;
grant select(id,institution_id,tipo,fornecedor,rotulo,config,escopo,status,aceite_operador_em,ultimo_teste_em,ultimo_sync_em,ultimo_erro,created_at,updated_at) on public.vertice_data_connections to authenticated;
grant select on public.vertice_data_connection_runs to authenticated;
grant all on public.vertice_data_connections, public.vertice_data_connection_runs to service_role;

create policy vertice_data_connections_select on public.vertice_data_connections for select to authenticated
 using (public.vertice_connection_authorize(institution_id));
create policy vertice_data_connection_runs_select on public.vertice_data_connection_runs for select to authenticated
 using (public.vertice_connection_authorize(institution_id));

-- Guarda a credencial no cofre; só o service_role executa (chamado pela edge function).
create or replace function public.vertice_connection_store_secret(p_conn uuid, p_secret text)
returns uuid language plpgsql security definer set search_path to '' as $$
declare v_id uuid; v_old uuid;
begin
 select vault_secret_id into v_old from public.vertice_data_connections where id=p_conn;
 v_id:=vault.create_secret(p_secret,'conexao_'||p_conn::text||'_'||extract(epoch from now())::bigint::text,'Credencial de conexao de dados da IES');
 update public.vertice_data_connections set vault_secret_id=v_id,updated_at=now() where id=p_conn;
 if v_old is not null then delete from vault.secrets where id=v_old; end if;
 return v_id;
end;$$;
create or replace function public.vertice_connection_read_secret(p_conn uuid)
returns text language sql security definer set search_path to '' as $$
 select ds.decrypted_secret from public.vertice_data_connections c join vault.decrypted_secrets ds on ds.id=c.vault_secret_id where c.id=p_conn;
$$;
create or replace function public.vertice_connection_drop_secret(p_conn uuid)
returns void language plpgsql security definer set search_path to '' as $$
declare v_old uuid;
begin
 select vault_secret_id into v_old from public.vertice_data_connections where id=p_conn;
 update public.vertice_data_connections set vault_secret_id=null,status='pausada',updated_at=now() where id=p_conn;
 if v_old is not null then delete from vault.secrets where id=v_old; end if;
end;$$;
revoke all on function public.vertice_connection_store_secret(uuid,text), public.vertice_connection_read_secret(uuid), public.vertice_connection_drop_secret(uuid) from public, anon, authenticated;
grant execute on function public.vertice_connection_store_secret(uuid,text), public.vertice_connection_read_secret(uuid), public.vertice_connection_drop_secret(uuid) to service_role;
revoke all on function public.vertice_connection_authorize(uuid) from public, anon;
grant execute on function public.vertice_connection_authorize(uuid) to authenticated, service_role;

alter table public.vertice_data_connections
 add column if not exists escopo_financeiro text not null default 'nenhum' check (escopo_financeiro in ('nenhum','pessoal','completo')),
 add column if not exists aceite_financeiro_em timestamptz,
 add column if not exists aprovado_por uuid,
 add column if not exists aprovado_em timestamptz;
alter table public.vertice_data_connections drop constraint if exists vertice_data_connections_status_check;
alter table public.vertice_data_connections add constraint vertice_data_connections_status_check check (status in ('pendente','aguardando_aprovacao','ativa','erro','pausada'));
alter table public.vertice_data_connection_runs drop constraint if exists vertice_data_connection_runs_acao_check;
alter table public.vertice_data_connection_runs add constraint vertice_data_connection_runs_acao_check check (acao in ('criar','testar','sincronizar','pausar','retomar','revogar','aprovar'));
grant select(escopo_financeiro,aceite_financeiro_em,aprovado_em) on public.vertice_data_connections to authenticated;
create or replace function public.vertice_connection_master()
returns boolean language sql stable set search_path to '' as $$
 select coalesce(auth.uid() is not null and auth.jwt()->>'aal'='aal2' and vertice_private.is_master(),false);
$$;
revoke all on function public.vertice_connection_master() from public, anon;
grant execute on function public.vertice_connection_master() to authenticated, service_role;

create table if not exists public.vertice_connection_records(
 id bigint generated always as identity primary key,
 connection_id uuid not null references public.vertice_data_connections(id) on delete cascade,
 institution_id uuid not null,
 dataset text not null,
 categoria text not null check (categoria in ('academico_agregado','academico_nominal','pessoal','financeiro')),
 row_hash text not null,
 payload jsonb not null,
 synced_at timestamptz not null default now(),
 unique (connection_id, dataset, row_hash)
);
create index if not exists vertice_connection_records_inst on public.vertice_connection_records(institution_id, dataset);
alter table public.vertice_connection_records enable row level security;
revoke all on public.vertice_connection_records from anon, authenticated;
grant select on public.vertice_connection_records to authenticated;
grant all on public.vertice_connection_records to service_role;
create policy vertice_connection_records_select on public.vertice_connection_records for select to authenticated
 using (public.vertice_connection_authorize(institution_id));
alter table public.vertice_data_connection_runs drop constraint if exists vertice_data_connection_runs_acao_check;
alter table public.vertice_data_connection_runs add constraint vertice_data_connection_runs_acao_check check (acao in ('criar','testar','sincronizar','pausar','retomar','revogar','aprovar'));
